mapper.select:
SELECT * FROM (
  SELECT 
    ROW_NUMBER() OVER (


          ORDER BY ${sortField} ${sortOrder}


          ORDER BY b.borrowId


    ) AS row_num,
    b.borrowId, b.userId, b.bookId, b.borrowTime, b.returnTime,
    u.userName, bi.bookName
  FROM borrow b WITH(NOLOCK)
  JOIN [user] u WITH(NOLOCK) ON b.userId = u.userId
  JOIN book_info bi WITH(NOLOCK) ON b.bookId = bi.bookId


      AND u.userName LIKE '%' + #{username} + '%'


      AND bi.bookName LIKE '%' + #{bookname} + '%'


      AND b.userId = #{userid}


) AS temp
WHERE row_num BETWEEN #{begin} + 1 AND #{begin} + #{size}
